diff --git a/build.xml b/build.xml
index e9f85364d..0bbf2827c 100644
--- a/build.xml
+++ b/build.xml
@@ -16,8 +16,8 @@
 <project name="compiler" basedir="." default="jar" xmlns:artifact="antlib:org.apache.maven.artifact.ant">

   <!-- Force java 6 -->
-  <property name="ant.build.javac.source" value="1.6" />
-  <property name="ant.build.javac.target" value="1.6" />
+  <property name="ant.build.javac.source" value="1.8" />
+  <property name="ant.build.javac.target" value="1.8" />

   <!-- define other variables -->
   <property name="src.dir" value="${basedir}/src" />
diff --git a/src/com/google/javascript/jscomp/InlineVariables.java b/src/com/google/javascript/jscomp/InlineVariables.java
index 18c9fbe2c..605fc750c 100644
--- a/src/com/google/javascript/jscomp/InlineVariables.java
+++ b/src/com/google/javascript/jscomp/InlineVariables.java
@@ -253,12 +253,14 @@ class InlineVariables implements CompilerPass {
         // complex inlining heuristics.
         Reference reference = referenceInfo.references.get(
             firstRefAfterInit - 1);
-        if (canInline(declaration, init, reference)) {
+        if (canInline(declaration, init, reference) &&
+            !shouldNotInlineParameterAlias(v, init)) {
           inline(v, declaration, init, reference);
           staleVars.add(v);
         }
       } else if (declaration != init && refCount == 2) {
-        if (isValidDeclaration(declaration) && isValidInitialization(init)) {
+        if (isValidDeclaration(declaration) && isValidInitialization(init) &&
+            !shouldNotInlineParameterAlias(v, init)) {
           // The only reference is the initialization, remove the assignment and
           // the variable declaration.
           Node value = init.getAssignedValue();
@@ -648,10 +650,11 @@ class InlineVariables implements CompilerPass {
       }

       boolean isNeverAssigned = refInfo.isNeverAssigned();
+      Reference refInit = null;
       // For values that are never assigned, only the references need to be
       // checked.
       if (!isNeverAssigned) {
-        Reference refInit = refInfo.getInitializingReference();
+        refInit = refInfo.getInitializingReference();
         if (!isValidInitialization(refInit)) {
           return false;
         }
@@ -687,7 +690,98 @@ class InlineVariables implements CompilerPass {
         }
       }

+      // If the assigned value is a reference to a parameter and the function
+      // modifies the arguments object, we cannot inline it.
+      if (refInit != null) {
+        Node assignedValue = refInit.getAssignedValue();
+        if (assignedValue != null && assignedValue.getType() == Token.NAME) {
+          Var paramVar = v.scope.getVar(assignedValue.getString());
+          if (paramVar != null && isParameter(paramVar) &&
+              functionModifiesArguments(v)) {
+            return false;
+          }
+        }
+      }
+
       return true;
     }
+
+    /**
+     * Determines whether the variable is a function parameter.
+     */
+    private boolean isParameter(Var var) {
+      Node parent = var.getParentNode();
+      return parent != null && parent.getType() == Token.LP;
+    }
+
+    /**
+     * Determines whether the function containing the variable modifies
+     * the arguments object.
+     */
+    private boolean functionModifiesArguments(Var var) {
+      // Get the function node that contains this variable
+      Node scopeRoot = var.scope.getRootNode();
+      return scopeRootModifiesArguments(scopeRoot);
+    }
+
+    /**
+     * Checks if a scope root node modifies the arguments object.
+     */
+    private boolean scopeRootModifiesArguments(Node scopeRoot) {
+      if (scopeRoot.getType() != Token.FUNCTION) {
+        return false;
+      }
+      // Check all nodes in the function body for modifications to arguments
+      return modifiesArguments(scopeRoot);
+    }
+
+    /**
+     * Checks if a node or any of its descendants modify or escape the arguments object.
+     * This includes direct modifications like arguments[0] = ... and passing arguments
+     * to functions.
+     */
+    private boolean modifiesArguments(Node node) {
+      // Check if this node is an assignment to arguments[...] or arguments.property
+      if (node.getType() == Token.ASSIGN) {
+        Node lhs = node.getFirstChild();
+        if (isArgumentsElementAccess(lhs)) {
+          return true;
+        }
+      }
+
+      // Check if arguments is passed as an argument to a function call
+      if (node.getType() == Token.CALL) {
+        // Check all arguments to the call
+        for (Node arg = node.getFirstChild().getNext(); arg != null; arg = arg.getNext()) {
+          if (arg.getType() == Token.NAME && "arguments".equals(arg.getString())) {
+            return true;
+          }
+        }
+      }
+
+      // Recursively check children, but don't descend into nested functions
+      for (Node child = node.getFirstChild(); child != null; child = child.getNext()) {
+        if (child.getType() != Token.FUNCTION) {
+          if (modifiesArguments(child)) {
+            return true;
+          }
+        }
+      }
+
+      return false;
+    }
+
+    /**
+     * Checks if a node is an element access on the arguments object.
+     * For example: arguments[0] or arguments.length
+     */
+    private boolean isArgumentsElementAccess(Node node) {
+      if (node.getType() == Token.GETELEM || node.getType() == Token.GETPROP) {
+        Node obj = node.getFirstChild();
+        return obj != null && obj.getType() == Token.NAME &&
+            "arguments".equals(obj.getString());
+      }
+      return false;
+    }
   }
 }
